import json, statistics as stats
from pathlib import Path

def summarize(path, key_fields):
    rows = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    grouped = {}
    for r in rows:
        k = tuple(r[k] for k in key_fields)
        grouped.setdefault(k, []).append(r['t_total_ms'])
    out = []
    for k, vals in grouped.items():
        entry = {field: k[i] for i, field in enumerate(key_fields)}
        entry['p50_ms'] = stats.median(vals)
        entry['p95_ms'] = stats.quantiles(vals, n=20)[18] if len(vals) >= 20 else max(vals)
        out.append(entry)
    return out

files = {
    'pq_roundtrip': (Path('benchmarks/results/pq_roundtrip.jsonl'), ['size','sparsity']),
    'kernel_dense_vs_pq': (Path('benchmarks/results/kernel_dense_vs_pq.jsonl'), ['size','sparsity','mode']),
    'pq_block_sweep': (Path('benchmarks/results/pq_block_sweep.jsonl'), ['size','sparsity','block_elems']),
}

summary = {}
for name, (path, fields) in files.items():
    if path.exists():
        summary[name] = summarize(path, fields)

print(json.dumps(summary, indent=2, sort_keys=True))
